use serde::Deserialize;
use toml::Table;

/// One `[[metadata]]` entry: a file generated by a named provider and
/// written below the crate directory.
#[derive(Debug, Deserialize)]
pub struct MetadataSpec {
    /// Name of the registered provider (e.g. `iconify_aliases`).
    pub provider: String,
    /// Output path below the crate directory.
    pub output: String,
    /// Provider-specific parameters (`with.*` inline keys).
    #[serde(default)]
    pub with: Table,
}
